int netdev_gtpu_build_header ( const struct netdev * netdev , struct ovs_action_push_tnl * data , const struct netdev_tnl_build_header_params * params ) { struct netdev_vport * dev = netdev_vport_cast ( netdev ) ; struct netdev_tunnel_config * tnl_cfg ; struct gtpuhdr * gtph ; unsigned int gtpu_hlen ; ovs_mutex_lock ( & dev -> mutex ) ; tnl_cfg = & dev -> tnl_cfg ; gtph -> md . flags = params -> flow -> tunnel . gtpu_flags ?params -> flow -> tunnel . gtpu_flags : GTPU_FLAGS_DEFAULT ; gtph -> md . msgtype = params -> flow -> tunnel . gtpu_msgtype ?params -> flow -> tunnel . gtpu_msgtype : GTPU_MSGTYPE_GPDU ; put_16aligned_be32 ( & gtph -> teid , be64_to_be32 ( params -> flow -> tunnel . tun_id ) ) ; gtpu_hlen = sizeof gtph ; if ( tnl_cfg -> set_seq ) { gtph -> md . flags |= GTPU_S_MASK ; gtpu_hlen += sizeof ( gtpuhdr_opt ) ; } ovs_mutex_unlock ( & dev -> mutex ) ; data -> header_len += gtpu_hlen ; data -> tnl_type = OVS_VPORT_TYPE_GTPU ; return 0 ; } 